import STCORE as c

REGRESSION_DEFINITIONS = [
  ('linear regression','FITS A STRAIGHT LINE TO PAIRED NUMERICAL (x,y) DATA TO PREDICT y FROM x. yhat=a+b*x, OR yhat=m*x+c: m=b IS SLOPE AND c=a IS INTERCEPT.'),
  ('least squares regression line','THE LINE THAT MINIMIZES SUM((y-yhat)^2), THE SUM OF SQUARED VERTICAL RESIDUALS. b=Sxy/Sxx; a=ybar-b*xbar. THE LINE PASSES THROUGH (xbar,ybar).'),
  ('explanatory variable','x: THE PREDICTOR OR INDEPENDENT VARIABLE, PLOTTED ON THE HORIZONTAL AXIS. USED TO PREDICT THE RESPONSE; THIS NAME DOES NOT ESTABLISH CAUSATION.'),
  ('response variable','y: THE RESPONSE OR DEPENDENT VARIABLE, PLOTTED ON THE VERTICAL AXIS. y IS OBSERVED; yhat IS PREDICTED BY THE LINE.'),
  ('slope','b IN yhat=a+b*x: THE CHANGE IN PREDICTED y FOR EACH 1-UNIT INCREASE IN x. UNITS ARE y UNITS PER x UNIT. POSITIVE MEANS INCREASING; NEGATIVE MEANS DECREASING.'),
  ('y intercept','a IN yhat=a+b*x: PREDICTED y WHEN x=0. HAS y UNITS; MAY HAVE NO PRACTICAL MEANING IF x=0 IS OUTSIDE THE DATA RANGE.'),
  ('predicted value','yhat: THE FITTED VALUE OF y FOR A GIVEN x. SUBSTITUTE x INTO THE REGRESSION EQUATION. KEEP FULL PRECISION IN COEFFICIENTS UNTIL ROUNDING THE FINAL PREDICTION. FOR TEXTBOOK EQUATION / MEAN / DNE CHOICES: REQUIRE x WITHIN THE OBSERVED RANGE; USE THE LINE IF CORRELATION IS SIGNIFICANT, OTHERWISE USE MEAN y.'),
  ('residual','e=y-yhat: OBSERVED MINUS PREDICTED y. POSITIVE: POINT ABOVE THE LINE; NEGATIVE: BELOW. HAS y UNITS. A RESIDUAL PLOT SHOWS RESIDUALS AGAINST x WITH A ZERO REFERENCE LINE.'),
  ('correlation coefficient r','PEARSON r MEASURES DIRECTION AND STRENGTH OF LINEAR ASSOCIATION: -1<=r<=1. NEAR +/-1 IS STRONG LINEAR ASSOCIATION; r=0 MEANS NO LINEAR ASSOCIATION, BUT A NONLINEAR PATTERN MAY EXIST. UNITLESS; UNDEFINED IF EITHER VARIABLE IS CONSTANT.'),
  ('coefficient of determination r squared','r^2 describes how much of the variation in y is explained by using x to predict y with a straight line. Variation means how much the y values differ from their average. Example: r^2=.80 means 80% of the variation in y is explained by its linear relationship with x. It does not mean 80% of predictions are correct, or prove that x causes y.'),
  ('scatterplot','GRAPH OF PAIRED (x,y) VALUES. CHECK DIRECTION, FORM, STRENGTH AND OUTLIERS BEFORE INTERPRETING A LINEAR FIT.'),
  ('interpolation','PREDICTING y AT AN x INSIDE THE OBSERVED x RANGE.'),
  ('extrapolation','PREDICTING y AT AN x OUTSIDE THE OBSERVED x RANGE. THE OBSERVED LINEAR PATTERN MAY NOT CONTINUE THERE.'),
  ('influential point','A POINT WHOSE REMOVAL SUBSTANTIALLY CHANGES THE FITTED LINE. A POINT FAR FROM THE OTHER x VALUES HAS HIGH LEVERAGE; IT IS NOT NECESSARILY INFLUENTIAL.'),
  ('correlation and causation','ASSOCIATION ALONE DOES NOT SHOW THAT CHANGING x CAUSES y TO CHANGE. CONFOUNDING VARIABLES OR OTHER EXPLANATIONS MAY PRODUCE THE ASSOCIATION.')]

def get_definitions(index=None):
  return REGRESSION_DEFINITIONS if index is None else REGRESSION_DEFINITIONS[index]

def menu():
  while True:
    key=c.menu('REGRESSION DEFINITIONS',[(str(i+1),row[0].upper()) for i,row in enumerate(REGRESSION_DEFINITIONS)])
    if key=='0': return
    title,definition=REGRESSION_DEFINITIONS[int(key)-1]
    c.call('STPAGE','text_pages',title,definition)
